//! Compatibility with the files MacVPN 0.4.0 (Swift) writes and reads.
//!
//! `fixtures/swift/` was generated by the 0.x Swift app's real `ConnectionStore`, `ConnectionRankingStore` and
//! `SystemOTPStore` and is frozen (see `fixtures/swift/README.md`). The Rust side must read every Swift-written file and write it
//! back byte for byte, and for every hand-written input (`inputs/`) it must load exactly what Swift loads (or
//! reject exactly what Swift rejects) — `decoded/` holds Swift's re-encoded result or `INVALID`. Byte-identical
//! output also proves the other direction: Swift reads what Rust writes, because it is what Swift writes itself.

mod common;

use common::TempDir;
use macvpn_core::collation;
use macvpn_core::date::Date;
use macvpn_core::models::{Connection, NativeSettings, OTPSeparator, OTPSetting, VPNKind, parse_uuid};
use macvpn_core::ranking::{ConnectionRanking, ConnectionRankingStore, UsageStats};
use macvpn_core::store::ConnectionStore;
use macvpn_core::swift_json;
use macvpn_core::system_otp::SystemOTPStore;
use std::cmp::Ordering;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/swift")
}

fn json_files(dir: &Path) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = fs::read_dir(dir)
        .unwrap()
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    v.sort();
    assert!(!v.is_empty(), "no fixtures in {}", dir.display());
    v
}

fn read(path: &Path) -> String {
    fs::read_to_string(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn decode_meta(bytes: &[u8]) -> Option<Connection> {
    Connection::from_json(&swift_json::parse(bytes).ok()?).ok()
}

#[test]
fn swift_written_meta_round_trips_byte_for_byte() {
    for path in json_files(&fixtures().join("meta")) {
        let text = read(&path);
        let c = decode_meta(text.as_bytes()).unwrap_or_else(|| panic!("cannot decode {}", path.display()));
        let back = swift_json::to_pretty_sorted(&c.to_json()).unwrap();
        assert_eq!(back, text, "{}", path.display());
    }
}

#[test]
fn swift_written_meta_has_the_expected_fields() {
    let load = |name: &str| decode_meta(read(&fixtures().join("meta").join(name)).as_bytes()).unwrap();
    let full = load("openvpn-full.json");
    assert_eq!(full.id, parse_uuid("0A1B2C3D-4E5F-4061-8273-94A5B6C7D8E9").unwrap());
    assert_eq!(full.name, "Office VPN");
    assert_eq!(full.kind, VPNKind::Openvpn);
    assert_eq!(full.created_at, Date::from_time_interval_since_1970(1_792_173_300.0));
    assert_eq!(full.acknowledged_risky_directives, ["group", "user"]);
    assert_eq!(full.otp, OTPSetting::new(true, OTPSeparator::Colon));
    let l2tp = load("l2tp.json");
    assert_eq!(l2tp.kind, VPNKind::L2tp);
    assert_eq!(l2tp.native_service_name.as_deref(), Some("MacVPN Office L2TP"));
    assert_eq!(l2tp.native_service_id.as_deref(), Some("38B51E6D-5D77-4ABE-BFDF-B0E5DE45B1C4"));
    assert_eq!(
        l2tp.native,
        Some(NativeSettings {
            server: "vpn.example.com".into(),
            account: "bob".into(),
            group_name: String::new(),
            send_all_traffic: true
        })
    );
    let cisco = load("cisco.json");
    assert_eq!(cisco.native.as_ref().map(|n| (n.group_name.as_str(), n.send_all_traffic)), Some(("staff", false)));
    assert_eq!(load("special-chars.json").name, "a/b \"q\" \\ \t\n\r\u{1}\u{8}\u{C}\u{1F}\u{7F} é 🇭🇺 \u{2028} <&> ' ~");
    for (file, kind) in
        [("wireguard.json", VPNKind::Wireguard), ("strongswan.json", VPNKind::Strongswan), ("sstp.json", VPNKind::Sstp)]
    {
        assert_eq!(load(file).kind, kind, "{file}");
    }
}

/// Rust writes exactly what Swift wrote for the same values.
#[test]
fn rust_writes_what_swift_writes() {
    let tmp = TempDir::new();
    let store = ConnectionStore::new(tmp.path());
    let created = Date::parse_iso8601("2026-10-16T17:55:00Z").unwrap();
    let mut c = Connection::with_id(
        parse_uuid("55555555-6666-7777-8888-999999999999").unwrap(),
        "Office L2TP",
        VPNKind::L2tp,
        created,
    );
    c.native_service_name = Some("MacVPN Office L2TP".into());
    c.native_service_id = Some("38B51E6D-5D77-4ABE-BFDF-B0E5DE45B1C4".into());
    c.native = Some(NativeSettings { server: "vpn.example.com".into(), account: "bob".into(), ..Default::default() });
    store.save(&c, None).unwrap();
    assert_eq!(read(&store.meta_path(&c.id)), read(&fixtures().join("meta/l2tp.json")));

    let mut full = Connection::with_id(
        parse_uuid("0A1B2C3D-4E5F-4061-8273-94A5B6C7D8E9").unwrap(),
        "Office VPN",
        VPNKind::Openvpn,
        Date::from_time_interval_since_1970(1_792_173_300.75),
    );
    full.acknowledged_risky_directives = vec!["group".into(), "user".into()];
    full.otp = OTPSetting::new(true, OTPSeparator::Colon);
    store.save(&full, None).unwrap();
    assert_eq!(read(&store.meta_path(&full.id)), read(&fixtures().join("meta/openvpn-full.json")));
}

/// Hand-written (older, newer, hand-edited, broken) `meta.json` files load exactly as in Swift.
#[test]
fn meta_inputs_decode_like_swift() {
    for input in json_files(&fixtures().join("inputs/meta")) {
        let name = input.file_name().unwrap();
        let expected = read(&fixtures().join("decoded/meta").join(name));
        // Through the real list() path, like the Swift generator.
        let tmp = TempDir::new();
        let dir = tmp.path().join(uuid::Uuid::new_v4().to_string());
        fs::create_dir_all(&dir).unwrap();
        fs::copy(&input, dir.join("meta.json")).unwrap();
        let store = ConnectionStore::new(tmp.path());
        let loaded = store.list().unwrap();
        match loaded.first() {
            None => assert_eq!(expected, "INVALID\n", "Rust rejected {name:?}, Swift loaded it"),
            Some(c) => {
                assert_ne!(expected, "INVALID\n", "Rust loaded {name:?}, Swift rejected it");
                let back = TempDir::new();
                let store = ConnectionStore::new(back.path());
                store.save(c, None).unwrap();
                assert_eq!(read(&store.meta_path(&c.id)), expected, "{name:?}");
            }
        }
    }
}

#[test]
fn swift_written_ranking_round_trips_byte_for_byte() {
    for path in json_files(&fixtures().join("connection-order")) {
        let tmp = TempDir::new();
        let loaded = ConnectionRankingStore::new(&path).load();
        let out = ConnectionRankingStore::new(tmp.path().join("MacVPN/connection-order.json"));
        out.save(&loaded).unwrap();
        assert_eq!(read(&out.path), read(&path), "{}", path.display());
    }
}

/// The same operations give the same scores, bit for bit, and the same file.
#[test]
fn ranking_arithmetic_matches_swift() {
    let t0 = Date::from_time_interval_since_1970(1_800_000_000.0);
    let day = 24.0 * 60.0 * 60.0;
    let mut r = ConnectionRanking::default();
    r.record_success("11111111-2222-3333-4444-555555555555", t0);
    r.record_success("11111111-2222-3333-4444-555555555555", t0.adding(3.0 * day));
    r.record_success("38B51E6D-5D77-4ABE-BFDF-B0E5DE45B1C4", t0.adding(0.5));
    r.pin("22222222-3333-4444-5555-666666666666");
    r.pin("11111111-2222-3333-4444-555555555555");
    let tmp = TempDir::new();
    let store = ConnectionRankingStore::new(tmp.path().join("connection-order.json"));
    store.save(&r).unwrap();
    assert_eq!(read(&store.path), read(&fixtures().join("connection-order/recorded.json")));

    let usage: HashMap<String, UsageStats> = [
        ("a", 1.5e-7),
        ("b", 1e16),
        ("c", 123.456),
        ("d", 0.0001),
        ("e", 1e15),
        ("f", 0.0),
        ("g", 2.5e-308),
        ("h", f64::MAX),
        ("i", 0.1 + 0.2),
        ("j", 12_345_678.9),
        ("k", 5e-324),
        ("l", 9_007_199_254_740_993.0),
    ]
    .into_iter()
    .map(|(k, s)| (k.to_string(), UsageStats { score: s, last_updated: t0 }))
    .collect();
    store.save(&ConnectionRanking::new(Vec::new(), usage)).unwrap();
    assert_eq!(read(&store.path), read(&fixtures().join("connection-order/numbers.json")));
    store.save(&ConnectionRanking::default()).unwrap();
    assert_eq!(read(&store.path), read(&fixtures().join("connection-order/empty.json")));
}

#[test]
fn ranking_inputs_decode_like_swift() {
    for input in json_files(&fixtures().join("inputs/connection-order")) {
        let name = input.file_name().unwrap();
        let tmp = TempDir::new();
        let out = ConnectionRankingStore::new(tmp.path().join("connection-order.json"));
        out.save(&ConnectionRankingStore::new(&input).load()).unwrap();
        assert_eq!(read(&out.path), read(&fixtures().join("decoded/connection-order").join(name)), "{name:?}");
    }
}

#[test]
fn system_otp_matches_swift() {
    let tmp = TempDir::new();
    let store = SystemOTPStore::new(tmp.path().join("system-otp.json"));
    let map: HashMap<String, OTPSetting> = [
        ("38B51E6D-5D77-4ABE-BFDF-B0E5DE45B1C4", OTPSetting::new(true, OTPSeparator::Comma)),
        ("DISABLED-IS-DROPPED", OTPSetting::new(false, OTPSeparator::Colon)),
        ("0F9E8D7C-6B5A-4938-2716-05F4E3D2C1B0", OTPSetting::new(true, OTPSeparator::None)),
        ("A1", OTPSetting::new(true, OTPSeparator::Colon)),
    ]
    .into_iter()
    .map(|(k, v)| (k.to_string(), v))
    .collect();
    store.save(&map).unwrap();
    assert_eq!(read(&store.path), read(&fixtures().join("system-otp/saved.json")));
    store.save(&HashMap::new()).unwrap();
    assert_eq!(read(&store.path), read(&fixtures().join("system-otp/empty.json")));
    for path in json_files(&fixtures().join("system-otp")) {
        store.save(&SystemOTPStore::new(&path).load()).unwrap();
        assert_eq!(read(&store.path), read(&path), "{}", path.display());
    }
}

#[test]
fn system_otp_inputs_decode_like_swift() {
    for input in json_files(&fixtures().join("inputs/system-otp")) {
        let name = input.file_name().unwrap();
        let tmp = TempDir::new();
        let out = SystemOTPStore::new(tmp.path().join("system-otp.json"));
        out.save(&SystemOTPStore::new(&input).load()).unwrap();
        assert_eq!(read(&out.path), read(&fixtures().join("decoded/system-otp").join(name)), "{name:?}");
    }
}

/// `list()` order: Swift sorted these names with `localizedCaseInsensitiveCompare` under en_US. The core's
/// default comparator must agree on every pair Swift distinguishes (ties keep the directory order in both).
/// The exact per-locale order (e.g. Hungarian `cs`, `ö`) comes from the platform comparator.
#[test]
fn default_name_order_agrees_with_swift_en_us() {
    let swift: Vec<String> = read(&fixtures().join("list-order-en_US.txt")).lines().map(str::to_string).collect();
    assert_eq!(swift.len(), 23);
    for i in 0..swift.len() {
        for j in i + 1..swift.len() {
            assert_ne!(
                collation::default_compare(&swift[i], &swift[j]),
                Ordering::Greater,
                "{} should not sort after {}",
                swift[i],
                swift[j]
            );
        }
    }
    // And through ConnectionStore::list() itself.
    let tmp = TempDir::new();
    let store = ConnectionStore::new(tmp.path());
    let created = Date::parse_iso8601("2026-10-16T17:55:00Z").unwrap();
    for name in swift.iter().rev() {
        store.save(&Connection::with_id(uuid::Uuid::new_v4(), name, VPNKind::Wireguard, created), None).unwrap();
    }
    let listed: Vec<String> = store.list().unwrap().into_iter().map(|c| c.name).collect();
    for i in 0..listed.len() {
        for j in i + 1..listed.len() {
            let (a, b) = (&listed[i], &listed[j]);
            let (si, sj) = (swift.iter().position(|s| s == a).unwrap(), swift.iter().position(|s| s == b).unwrap());
            if collation::default_compare(a, b) != Ordering::Equal {
                assert!(si < sj, "{a} / {b}");
            }
        }
    }
}
